// Echo-style demo of the governed action (Stream E). It deliberately writes
// nowhere: the point being proved is the GOVERNANCE path — plan → SUNIL's
// params model → permission ask_user → owner approval → chokepoint → this tool
// — not the storage. Replacing this body with a real write changes nothing
// about who is allowed to call it.
const project_key = String(query.project_key ?? '').trim();
const summary = String(query.summary ?? '').trim();
if (!project_key || !summary) {
  return JSON.stringify({ ok: false, error: 'project_key and summary are both required' });
}
return JSON.stringify({
  ok: true,
  project_key,
  summary,
  recorded_at: new Date().toISOString(),
  recorded_by: 'n8n:sunil-mcp-server',
});

